// Provided by your instructor. Do not edit this file.
import { render, screen, waitFor, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it, vi } from 'vitest'
import { ApiError } from '../api'
import { AddIssueForm } from '../components/AddIssueForm'

async function fillIn(title: string, description: string, steps: string) {
  if (title) await userEvent.type(screen.getByLabelText('Title'), title)
  if (description) await userEvent.type(screen.getByLabelText('Description'), description)
  if (steps) await userEvent.type(screen.getByLabelText('Steps to reproduce'), steps)
}

// The box and its message live together in one Field (role="group").
function fieldOf(label: string): HTMLElement {
  return screen.getByLabelText(label).closest('[role="group"]') as HTMLElement
}

const submit = () => userEvent.click(screen.getByRole('button', { name: 'Add issue' }))

describe('AddIssueForm', () => {
  it('has Title, Description, Steps to reproduce and Priority fields and an Add issue button', () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    expect(screen.getByLabelText('Title')).toBeInTheDocument()
    expect(screen.getByLabelText('Description')).toBeInTheDocument()
    expect(screen.getByLabelText('Steps to reproduce')).toBeInTheDocument()
    expect(screen.getByLabelText('Priority')).toHaveValue('medium')
    expect(screen.getByRole('button', { name: 'Add issue' })).toBeInTheDocument()
  })

  it('shows a message next to every empty box and does not call onAdd', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await submit()
    for (const label of ['Title', 'Description', 'Steps to reproduce']) {
      expect(await within(fieldOf(label)).findByRole('alert')).toBeInTheDocument()
      expect(screen.getByLabelText(label)).toHaveAttribute('aria-invalid', 'true')
    }
    expect(screen.getByLabelText('Priority')).not.toHaveAttribute('aria-invalid', 'true')
    expect(onAdd).not.toHaveBeenCalled()
  })

  it('only complains about the box that is empty', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await fillIn('A title', '', 'Some steps')
    await submit()
    expect(await within(fieldOf('Description')).findByRole('alert')).toBeInTheDocument()
    expect(within(fieldOf('Title')).queryByRole('alert')).not.toBeInTheDocument()
    expect(within(fieldOf('Steps to reproduce')).queryByRole('alert')).not.toBeInTheDocument()
  })

  it('treats spaces only as empty', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('   ', 'A description', 'Some steps')
    await submit()
    expect(await within(fieldOf('Title')).findByRole('alert')).toBeInTheDocument()
    expect(onAdd).not.toHaveBeenCalled()
  })

  it('takes a message away as soon as the person fixes that box', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await submit()
    expect(await within(fieldOf('Title')).findByRole('alert')).toBeInTheDocument()
    await userEvent.type(screen.getByLabelText('Title'), 'Now it has a title')
    await waitFor(() => expect(within(fieldOf('Title')).queryByRole('alert')).not.toBeInTheDocument())
    expect(screen.getByLabelText('Title')).not.toHaveAttribute('aria-invalid', 'true')
  })

  it('calls onAdd with trimmed text and the chosen priority', async () => {
    const onAdd = vi.fn()
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('  Dark mode flickers  ', ' It flashes white ', ' Reload the page ')
    await userEvent.selectOptions(screen.getByLabelText('Priority'), 'high')
    await submit()
    await waitFor(() => expect(onAdd).toHaveBeenCalledTimes(1))
    expect(onAdd).toHaveBeenCalledWith({
      title: 'Dark mode flickers',
      description: 'It flashes white',
      stepsToReproduce: 'Reload the page',
      priority: 'high',
    })
  })

  it('clears the boxes after a good add', async () => {
    render(<AddIssueForm onAdd={vi.fn()} />)
    await fillIn('A title', 'A description', 'Some steps')
    await submit()
    await waitFor(() => expect(screen.getByLabelText('Title')).toHaveValue(''))
    expect(screen.getByLabelText('Description')).toHaveValue('')
    expect(screen.getByLabelText('Steps to reproduce')).toHaveValue('')
  })

  it('is switched off while the add is in progress, so a double click cannot add twice', async () => {
    let finish: () => void = () => {}
    const onAdd = vi.fn(() => new Promise<void>((resolve) => { finish = resolve }))
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await submit()
    await waitFor(() => expect(screen.getByRole('button', { name: 'Add issue' })).toBeDisabled())
    finish()
    await waitFor(() => expect(screen.getByRole('button', { name: 'Add issue' })).toBeEnabled())
    expect(onAdd).toHaveBeenCalledTimes(1)
  })

  it('puts the SERVER\'s field problems next to the right boxes (the server checks again)', async () => {
    const onAdd = vi.fn().mockRejectedValue(
      new ApiError(400, 'ValidationFailed', [
        { path: 'title', message: 'The server says: that title is taken' },
        { path: 'priority', message: 'The server says: pick a real priority' },
      ]),
    )
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await submit()
    expect(await within(fieldOf('Title')).findByText('The server says: that title is taken')).toBeInTheDocument()
    expect(within(fieldOf('Priority')).getByText('The server says: pick a real priority')).toBeInTheDocument()
    expect(screen.getByLabelText('Title')).toHaveAttribute('aria-invalid', 'true')
    expect(screen.getByLabelText('Title')).toHaveValue('A title')
  })

  it('shows the server message once, below the boxes, when the problem belongs to no box', async () => {
    const onAdd = vi.fn().mockRejectedValue(new ApiError(403, 'Your role may not issue:create'))
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await submit()
    expect(await screen.findByText('Your role may not issue:create')).toBeInTheDocument()
    expect(screen.getByLabelText('Title')).toHaveValue('A title')
    expect(screen.getByLabelText('Title')).not.toHaveAttribute('aria-invalid', 'true')
  })

  it('says it could not reach the server when the failure is not an ApiError', async () => {
    const onAdd = vi.fn().mockRejectedValue(new TypeError('Failed to fetch'))
    render(<AddIssueForm onAdd={onAdd} />)
    await fillIn('A title', 'A description', 'Some steps')
    await submit()
    expect(await screen.findByText('Could not reach the server')).toBeInTheDocument()
  })

  it('starts with the values it is given, and uses a different button label, when editing', async () => {
    const onAdd = vi.fn()
    render(
      <AddIssueForm
        onAdd={onAdd}
        initial={{ title: 'Old title', description: 'Old description', stepsToReproduce: 'Old steps', priority: 'low' }}
        submitLabel="Save changes"
        clearOnSuccess={false}
      />,
    )
    expect(screen.getByLabelText('Title')).toHaveValue('Old title')
    expect(screen.getByLabelText('Priority')).toHaveValue('low')
    await userEvent.click(screen.getByRole('button', { name: 'Save changes' }))
    await waitFor(() => expect(onAdd).toHaveBeenCalledTimes(1))
    expect(onAdd).toHaveBeenCalledWith({
      title: 'Old title',
      description: 'Old description',
      stepsToReproduce: 'Old steps',
      priority: 'low',
    })
    expect(screen.getByLabelText('Title')).toHaveValue('Old title')
  })
})
